-- LeadFlow staging sanitizer — LEAK CHECK. Read-only. Returns ONLY failing checks (rule, table, column, count). No rows returned = PASS.
SELECT * FROM (
SELECT 'STRUCTURE' AS rule_name, u.t AS table_name, u.c AS column_name, 1 AS failing_rows FROM (SELECT ic.table_name AS t, ic.column_name AS c FROM information_schema.columns ic LEFT JOIN __column_map cm ON cm.t = ic.table_name AND cm.c = ic.column_name WHERE ic.table_schema = DATABASE() AND ic.table_name NOT LIKE '\_\_%' AND cm.t IS NULL) u
