UNION ALL SELECT 'FREE_TEXT' AS rule_name, 'activity_log' AS table_name, 'title' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE t.`title` IS NOT NULL AND t.`title` <> '' AND t.`title` NOT IN ('[]', '{}', LEFT('Sanitized text.', 255))
UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'activity_log' AS table_name, 'title' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE CAST(t.`title` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`title` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
UNION ALL SELECT 'FREE_TEXT' AS rule_name, 'activity_log' AS table_name, 'body' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE t.`body` IS NOT NULL AND t.`body` <> '' AND t.`body` NOT IN ('[]', '{}', 'Sanitized text.')
UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'activity_log' AS table_name, 'body' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE CAST(t.`body` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`body` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
UNION ALL SELECT 'JSON_EMPTY' AS rule_name, 'activity_log' AS table_name, 'meta' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE t.`meta` IS NOT NULL AND CAST(t.`meta` AS CHAR) NOT IN ('{}', '[]')
UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'activity_log' AS table_name, 'meta' AS column_name, COUNT(*) AS failing_rows FROM `activity_log` t WHERE CAST(t.`meta` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`meta` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
