UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'agents' AS table_name, 'name' AS column_name, COUNT(*) AS failing_rows FROM `agents` t WHERE CAST(t.`name` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`name` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
