UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'voice_calls' AS table_name, 'endedReason' AS column_name, COUNT(*) AS failing_rows FROM `voice_calls` t WHERE CAST(t.`endedReason` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`endedReason` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
UNION ALL SELECT 'PHONE_OR_EMAIL_IN_TEXT' AS rule_name, 'voice_calls' AS table_name, 'successEvaluation' AS column_name, COUNT(*) AS failing_rows FROM `voice_calls` t WHERE CAST(t.`successEvaluation` AS CHAR) REGEXP '(\\+1([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])[0-9]{7})|(\\(?([2-8][0-9]{2}|9[0-8][0-9]|99[0-8])\\)?[ .-][0-9]{3}[ .-][0-9]{4})' OR REGEXP_REPLACE(CAST(t.`successEvaluation` AS CHAR), '[A-Za-z0-9._%+-]+@example\\.invalid', '') REGEXP '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}'
UNION ALL SELECT 'NEUTRALIZE', 'always_on_enrollments', 'status', COUNT(*) FROM `always_on_enrollments` t WHERE t.status = 'PENDING'
UNION ALL SELECT 'NEUTRALIZE', 'always_on_groups', 'isActive', COUNT(*) FROM `always_on_groups` t WHERE t.isActive <> 0
UNION ALL SELECT 'NEUTRALIZE', 'booking_notification_deliveries', 'status', COUNT(*) FROM `booking_notification_deliveries` t WHERE t.status IN ('pending','sending')
UNION ALL SELECT 'NEUTRALIZE', 'booking_notification_deliveries', 'claimToken', COUNT(*) FROM `booking_notification_deliveries` t WHERE t.claimToken IS NOT NULL
UNION ALL SELECT 'NEUTRALIZE', 'booking_notification_deliveries', 'claimedAt', COUNT(*) FROM `booking_notification_deliveries` t WHERE t.claimedAt IS NOT NULL
UNION ALL SELECT 'NEUTRALIZE', 'lead_notification_deliveries', 'status', COUNT(*) FROM `lead_notification_deliveries` t WHERE t.status IN ('pending','sending')
UNION ALL SELECT 'NEUTRALIZE', 'lead_notification_deliveries', 'claimToken', COUNT(*) FROM `lead_notification_deliveries` t WHERE t.claimToken IS NOT NULL
UNION ALL SELECT 'NEUTRALIZE', 'lead_notification_deliveries', 'claimedAt', COUNT(*) FROM `lead_notification_deliveries` t WHERE t.claimedAt IS NOT NULL
UNION ALL SELECT 'NEUTRALIZE', 'campaign_approval_batches', 'status', COUNT(*) FROM `campaign_approval_batches` t WHERE t.status IN ('pending','approved')
UNION ALL SELECT 'NEUTRALIZE', 'confirmation_calls', 'status', COUNT(*) FROM `confirmation_calls` t WHERE t.status = 'pending'
UNION ALL SELECT 'NEUTRALIZE', 'conversation_sessions', 'autoFollowUpSent', COUNT(*) FROM `conversation_sessions` t WHERE t.autoFollowUpSent = 0
UNION ALL SELECT 'NEUTRALIZE', 'conversation_sessions', 'followUpSent', COUNT(*) FROM `conversation_sessions` t WHERE t.followUpSent = 0
UNION ALL SELECT 'NEUTRALIZE', 'conversation_sessions', 'madisonDeferredUntil', COUNT(*) FROM `conversation_sessions` t WHERE t.madisonDeferredUntil IS NOT NULL
UNION ALL SELECT 'NEUTRALIZE', 'inbound_sms', 'processingStatus', COUNT(*) FROM `inbound_sms` t WHERE t.processingStatus = 'pending'
UNION ALL SELECT 'NEUTRALIZE', 'madison_email_drafts', 'status', COUNT(*) FROM `madison_email_drafts` t WHERE t.status IN ('RECEIVED','CLASSIFIED','TOOLS_RUNNING','DRAFT_READY','SENDING')
UNION ALL SELECT 'NEUTRALIZE', 'madison_sms_drafts', 'status', COUNT(*) FROM `madison_sms_drafts` t WHERE t.status IN ('RECEIVED','CLASSIFIED','TOOLS_RUNNING','DRAFT_READY','SENDING')
UNION ALL SELECT 'NEUTRALIZE', 'nurture_enrollments', 'status', COUNT(*) FROM `nurture_enrollments` t WHERE t.status = 'active'
UNION ALL SELECT 'NEUTRALIZE', 'payable_invoice_attempts', 'state', COUNT(*) FROM `payable_invoice_attempts` t WHERE t.state IN ('pending','session_open')
UNION ALL SELECT 'NEUTRALIZE', 'payable_invoice_deliveries', 'state', COUNT(*) FROM `payable_invoice_deliveries` t WHERE t.state = 'pending'
UNION ALL SELECT 'NEUTRALIZE', 'payment_authorizations', 'status', COUNT(*) FROM `payment_authorizations` t WHERE t.status IN ('pending','authorized')
UNION ALL SELECT 'NEUTRALIZE', 'rating_sms_pending', 'status', COUNT(*) FROM `rating_sms_pending` t WHERE t.status IN ('pending','approved')
UNION ALL SELECT 'NEUTRALIZE', 'reactivation_campaigns', 'status', COUNT(*) FROM `reactivation_campaigns` t WHERE t.status = 'ACTIVE'
UNION ALL SELECT 'NEUTRALIZE', 'reactivation_contacts', 'status', COUNT(*) FROM `reactivation_contacts` t WHERE t.status = 'PENDING'
UNION ALL SELECT 'NEUTRALIZE', 'sms_campaigns', 'status', COUNT(*) FROM `sms_campaigns` t WHERE t.status IN ('FROZEN','APPROVED','SENDING')
UNION ALL SELECT 'NEUTRALIZE', 'sms_campaign_recipients', 'status', COUNT(*) FROM `sms_campaign_recipients` t WHERE t.status = 'PENDING'
UNION ALL SELECT 'NEUTRALIZE', 'twilio_lead_bridges', 'state', COUNT(*) FROM `twilio_lead_bridges` t WHERE t.state NOT IN ('completed','failed','cancelled') AND t.state NOT LIKE '%failed'
) checks WHERE failing_rows > 0 ORDER BY rule_name, table_name, column_name;
SELECT 'LEAK CHECK SUMMARY' AS step, 1230 AS checks_run;
